    51  // -----------------------------------------------------------------------------
    52  // This is an interface for an abstract stream class which is used for writing
    53  // the serialised results out.
    54  // -----------------------------------------------------------------------------
    55  class OTSStream {
    56   public:
    57    OTSStream() : chksum_(0) {}
    58
    59    virtual ~OTSStream() {}
    60
    61    // This should be implemented to perform the actual write.
    62    virtual bool WriteRaw(const void *data, size_t length) = 0;
    63
    64    bool Write(const void *data, size_t length) {
    65      if (!length) return false;
    66
    67      const size_t orig_length = length;
    68      size_t offset = 0;
    69
    70      size_t chksum_offset = Tell() & 3;
    71      if (chksum_offset) {
    72        const size_t l = std::min(length, static_cast<size_t>(4) - chksum_offset);
    73        uint32_t tmp = 0;
    74        std::memcpy(reinterpret_cast<uint8_t *>(&tmp) + chksum_offset, data, l);
    75        chksum_ += ots_ntohl(tmp);
    76        length -= l;
    77        offset += l;
    78      }
    79
    80      while (length >= 4) {
    81        uint32_t tmp;
    82        std::memcpy(&tmp, reinterpret_cast<const uint8_t *>(data) + offset,
    83          sizeof(uint32_t));
    84        chksum_ += ots_ntohl(tmp);
    85        length -= 4;
    86        offset += 4;
    87      }
    88
    89      if (length) {
    90        if (length > 4) return false;  // not reached
    91        uint32_t tmp = 0;
    92        std::memcpy(&tmp,
    93                    reinterpret_cast<const uint8_t*>(data) + offset, length);
    94        chksum_ += ots_ntohl(tmp);
    95      }
    96
    97      return WriteRaw(data, orig_length);
    98    }
    99
   100    virtual bool Seek(off_t position) = 0;
   101    virtual off_t Tell() const = 0;
   102
   103    virtual bool Pad(size_t bytes) {
   104      static const uint32_t kZero = 0;
   105      while (bytes >= 4) {
   106        if (!Write(&kZero, 4)) return false;
   107        bytes -= 4;
   108      }
   109      while (bytes) {
   110        static const uint8_t kZerob = 0;
   111        if (!Write(&kZerob, 1)) return false;
   112        bytes--;
   113      }
   114      return true;
   115    }
   116
   117    bool WriteU8(uint8_t v) {
   118      return Write(&v, sizeof(v));
   119    }
   120
   121    bool WriteU16(uint16_t v) {
   122      v = ots_htons(v);
   123      return Write(&v, sizeof(v));
   124    }
   125
   126    bool WriteS16(int16_t v) {
   127      v = ots_htons(v);
   128      return Write(&v, sizeof(v));
   129    }
   130
   131    bool WriteU24(uint32_t v) {
   132      v = ots_htonl(v);
   133      return Write(reinterpret_cast<uint8_t*>(&v)+1, 3);
   134    }
   135
   136    bool WriteU32(uint32_t v) {
   137      v = ots_htonl(v);
   138      return Write(&v, sizeof(v));
   139    }
   140
   141    bool WriteS32(int32_t v) {
   142      v = ots_htonl(v);
   143      return Write(&v, sizeof(v));
   144    }
   145
   146    bool WriteR64(uint64_t v) {
   147      return Write(&v, sizeof(v));
   148    }
